import type CONST from '@src/CONST';

import type {ValueOf} from 'type-fest';

import type * as OnyxCommon from './OnyxCommon';

/** How a domain account merge request gets resolved from the client */
type DomainAccountMergeRequestResolution = ValueOf<typeof CONST.DOMAIN_ACCOUNT_MERGE_REQUEST.RESOLUTION>;

/** A request to merge a domain-controlled account, waiting for a domain admin's decision */
type DomainAccountMergeRequest = {
    /** Unique ID of the request, generated by the server */
    requestID: string;

    /** Account ID of the member who submitted the request */
    requesterAccountID: number;

    /** Login of the domain-controlled account being merged */
    sourceLogin: string;

    /** Login of the account that remains after the merge */
    targetLogin?: string;

    /** The domain that controls the account being merged. The request is reviewed on this domain's Members page */
    domainAccountID?: number;

    /** The other domain of a cross-domain request */
    targetDomainAccountID?: number;

    /** When the request was generated, in UTC. The request expires 24 hours after this time */
    created: string;

    /** Client-only: the resolution the current user has sent and is waiting on the server for */
    pendingResolution?: DomainAccountMergeRequestResolution | null;

    /** Client-only: the resolution the server has accepted, kept until the UI has confirmed it to the user */
    resolution?: DomainAccountMergeRequestResolution | null;

    /** Errors from the latest failed action on the request */
    errors?: OnyxCommon.Errors | null;
};

export type {DomainAccountMergeRequestResolution};
export default DomainAccountMergeRequest;
